import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        double[] p = new double[n];
        for (int i = 0; i < n; i++) {
            p[i] = sc.nextDouble();
        }

        double[] answer = new double[n];
        double[] dp = new double[1 << n];
        double[] totalSum = new double[1 << n];

        // Function to count bits in an integer
        // Since Java doesn't have lambdas for this, define a method
        // But for performance, we can implement inline
        // Alternatively, define a static method
        // For clarity, define a static method below

        for (int mask = 0; mask < (1 << n); mask++) {
            double sumMask = 0.0;
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 1) {
                    sumMask += p[i];
                }
            }
            totalSum[mask] = sumMask;
        }

        dp[0] = 1.0;
        int flag = 0;

        for (int mask = 0; mask < (1 << n); mask++) {
            int bitsCount = countBits(mask);
            if (bitsCount > k) continue;
            if (dp[mask] < 1e-100) continue;
            if (bitsCount == k) flag = 1;
            double remaining = 1.0 - totalSum[mask];
            if (remaining < 1e-6) continue;
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 1) continue;
                double moveProb = dp[mask] * p[i] / remaining;
                dp[mask | (1 << i)] += moveProb;
            }
        }

        if (flag == 0) {
            for (int i = 0; i < n; i++) {
                answer[i] = (p[i] < 1e-6) ? 0.0 : 1.0;
            }
        } else {
            for (int mask = 0; mask < (1 << n); mask++) {
                if (countBits(mask) == k) {
                    for (int i = 0; i < n; i++) {
                        if (((mask >> i) & 1) == 1)
                            answer[i] += dp[mask];
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (i > 0) System.out.print(" ");
            System.out.printf("%.12f", answer[i]);
        }
        System.out.println();
    }

    // Static method to count bits
    public static int countBits(int x) {
        int cnt = 0;
        while (x != 0) {
            cnt += x & 1;
            x >>= 1;
        }
        return cnt;
    }
}

